296	// Used by list endpoints so we never ship full bodies for a 30-item list.
297	function parseAgentMeta(filePath) {
298	  try {
299	    const stats = fs.statSync(filePath);
300	    const hit = _agentCacheMeta.get(filePath);
301	    if (hit && hit.mtimeMs === stats.mtimeMs) return hit.meta;
302	
303	    // Read until we've consumed the second '---' line; cheaper than reading the
304	    // whole body only to throw it away. For files without frontmatter, fall
305	    // back to a full read via parseAgent (rare).
306	    const fd = fs.openSync(filePath, 'r');
307	    const buf = Buffer.alloc(64 * 1024);
308	    let collected = '';
309	    let bytesRead = 0;
310	    let pos = 0;
311	    let frontmatterEnd = -1;
312	    const FM_RE = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/;
313	    try {
314	      while (frontmatterEnd < 0) {
315	        const n = fs.readSync(fd, buf, 0, buf.length, pos);
316	        if (n === 0) break;
317	        collected += buf.slice(0, n).toString('utf-8');
318	        bytesRead += n;
319	        pos += n;
320	        const m = collected.match(FM_RE);
321	        if (m) frontmatterEnd = m[0].length;
322	        if (bytesRead > 256 * 1024 && frontmatterEnd < 0) break; // safety cap
323	      }
324	    } finally {
325	      fs.closeSync(fd);
326	    }
327	
328	    let data = {};
329	    let body = '';
330	    if (frontmatterEnd > 0) {
331	      const parsed = matter(collected.slice(0, frontmatterEnd + 1024)); // buffer margin
332	      data = parsed.data || {};
333	      // body is whatever follows the frontmatter — but we want LINE COUNT, not content.
334	      // A full mtime-based stat would be another syscall; estimate from file size instead.
