61	function checkBudget({ agentId, content, frontmatter }) {
62	  const { body, frontmatterText } = splitFrontmatter(content);
63	  const fm = frontmatter || tryParseFrontmatter(frontmatterText);
64	  const budget = resolveBudget(agentId, fm);
65	  const bodyLines = body.split('\n').length;
66	  const bodyChars = body.length;
67	
68	  const violations = [];
69	  const warnings = [];
70	
71	  if (bodyLines > budget.lines * HARD_FACTOR) {
72	    violations.push({ kind: 'lines', actual: bodyLines, budget: budget.lines, limit: Math.round(budget.lines * HARD_FACTOR) });
73	  } else if (bodyLines > budget.lines * WARN_FACTOR) {
74	    warnings.push({ kind: 'lines', actual: bodyLines, budget: budget.lines });
75	  }
76	
77	  if (bodyChars > budget.chars * HARD_FACTOR) {
78	    violations.push({ kind: 'chars', actual: bodyChars, budget: budget.chars, limit: Math.round(budget.chars * HARD_FACTOR) });
79	  } else if (bodyChars > budget.chars * WARN_FACTOR) {
80	    warnings.push({ kind: 'chars', actual: bodyChars, budget: budget.chars });
81	  }
82	
83	  return {
84	    ok: violations.length === 0 || budget.allowOversize,
85	    budget,
86	    actual: { lines: bodyLines, chars: bodyChars },
87	    violations,
88	    warnings,
89	    allowOversize: budget.allowOversize,
90	    suggestion: violations.length > 0
91	      ? `node scripts/compactor/compact.mjs ${agentId} --staging`
92	      : null,
93	  };
94	}
